static const char *known_libs[] = { "javaio", "javalang", "javalangreflect", "javanio", "javautil", "javanet", "dos95peer", "javalangmanagement", 0 };
static const char *last_error;
static const char *base_of(const char *path)
{
    const char *b = path;
    for (const char *p = path; *p; p++) if (*p == '\\' || *p == '/') b = p + 1;
    return b;
}
/* the handle is the library's index + 1; JNI_OnLoad is shared (jcl.c) and run once */
void *dos95_dlopen(const char *path)
{
    const char *b = base_of(path);
    char name[64]; size_t n = 0;
    if (!strncmp(b, "lib", 3)) b += 3;
    while (b[n] && b[n] != '.' && n < 63) { name[n] = b[n]; n++; }
    name[n] = 0;
    for (int i = 0; known_libs[i]; i++) if (!strcmp(known_libs[i], name)) return (void*)(long)(i + 1);
    last_error = "no such native library in this DOS95 build";
    return 0;
}
static int onload_done;
void *dos95_dlsym(void *handle, const char *sym)
{
    if (!strcmp(sym, "JNI_OnLoad")) { if (onload_done) return 0; onload_done = 1; }
    if (!strcmp(sym, "JNI_OnUnload")) return 0;
    for (int i = 0; syms[i].name; i++) if (!strcmp(syms[i].name, sym)) return (void*)syms[i].fn;
    last_error = "symbol not found";
    return 0;
}
const char *dos95_dlerror(void) { const char *e = last_error; last_error = 0; return e ? e : "unknown error"; }
